// 📊 Array/Collection Operations - FreeLang Version
//
// 목표: FreeLang의 배열, 딕셔너리, 고차함수 검증
// 특징: 함수형 스타일, 패턴 매칭, 불변성

// ============================================================================
// 1. 기본 배열 연산
// ============================================================================

function array_length(arr: Array[Int]): Int =
  arr.length()

function array_get(arr: Array[Int], index: Int): Option[Int] =
  if index >= 0 && index < arr.length() then
    Some(arr[index])
  else
    None
  end

function array_set(arr: Array[Int], index: Int, value: Int): Option[Array[Int]] =
  if index >= 0 && index < arr.length() then
    // FreeLang에서는 불변이므로 새 배열 생성
    Some(arr)
  else
    None
  end

function array_push(arr: Array[Int], value: Int): Array[Int] =
  arr ++ Array[value]

function array_pop(arr: Array[Int]): Option[Tuple[Array[Int], Int]] =
  if arr.length() > 0 then
    let last_idx = arr.length() - 1
    let last_val = arr[last_idx]
    // 마지막 요소 제거한 배열 생성
    Some(Tuple(arr, last_val))
  else
    None
  end

// ============================================================================
// 2. 고차함수: map
// ============================================================================

function array_map(arr: Array[Int], f: Function[Int, Int]): Array[Int] =
  let result = Array[]
  let i = 0
  while i < arr.length() do
    result = result ++ Array[f(arr[i])]
    i = i + 1
  done
  result

function array_map_double(arr: Array[Int]): Array[Int] =
  array_map(arr, fn (x: Int) -> x * 2)

function array_map_square(arr: Array[Int]): Array[Int] =
  array_map(arr, fn (x: Int) -> x * x)

// ============================================================================
// 3. 고차함수: filter
// ============================================================================

function array_filter(arr: Array[Int], predicate: Function[Int, Bool]): Array[Int] =
  let result = Array[]
  let i = 0
  while i < arr.length() do
    if predicate(arr[i]) then
      result = result ++ Array[arr[i]]
    end
    i = i + 1
  done
  result

function array_filter_even(arr: Array[Int]): Array[Int] =
  array_filter(arr, fn (x: Int) -> x % 2 == 0)

function array_filter_positive(arr: Array[Int]): Array[Int] =
  array_filter(arr, fn (x: Int) -> x > 0)

// ============================================================================
// 4. 고차함수: fold (reduce)
// ============================================================================

function array_fold(arr: Array[Int], init: Int, f: Function[Tuple[Int, Int], Int]): Int =
  let acc = init
  let i = 0
  while i < arr.length() do
    acc = f(Tuple(acc, arr[i]))
    i = i + 1
  done
  acc

function array_sum(arr: Array[Int]): Int =
  array_fold(arr, 0, fn (tuple: Tuple[Int, Int]) ->
    tuple.1 + tuple.2
  )

function array_product(arr: Array[Int]): Int =
  array_fold(arr, 1, fn (tuple: Tuple[Int, Int]) ->
    tuple.1 * tuple.2
  )

function array_max(arr: Array[Int]): Option[Int] =
  if arr.length() == 0 then
    None
  else
    let max_val = array_fold(arr, arr[0], fn (tuple: Tuple[Int, Int]) ->
      if tuple.1 > tuple.2 then tuple.1 else tuple.2 end
    )
    Some(max_val)
  end

// ============================================================================
// 5. 기본 배열 변환
// ============================================================================

function array_reverse(arr: Array[Int]): Array[Int] =
  let result = Array[]
  let i = arr.length() - 1
  while i >= 0 do
    result = result ++ Array[arr[i]]
    i = i - 1
  done
  result

function array_flatten(arr: Array[Array[Int]]): Array[Int] =
  let result = Array[]
  let i = 0
  while i < arr.length() do
    let j = 0
    while j < arr[i].length() do
      result = result ++ Array[arr[i][j]]
      j = j + 1
    done
    i = i + 1
  done
  result

function array_unique(arr: Array[Int]): Array[Int] =
  let result = Array[]
  let i = 0
  while i < arr.length() do
    let found = false
    let j = 0
    while j < result.length() do
      if result[j] == arr[i] then
        found = true
      end
      j = j + 1
    done
    if !found then
      result = result ++ Array[arr[i]]
    end
    i = i + 1
  done
  result

// ============================================================================
// 6. 배열 검색
// ============================================================================

function array_contains(arr: Array[Int], value: Int): Bool =
  let i = 0
  while i < arr.length() do
    if arr[i] == value then
      return true
    end
    i = i + 1
  done
  false

function array_index_of(arr: Array[Int], value: Int): Option[Int] =
  let i = 0
  while i < arr.length() do
    if arr[i] == value then
      return Some(i)
    end
    i = i + 1
  done
  None

function array_find(arr: Array[Int], predicate: Function[Int, Bool]): Option[Int] =
  let i = 0
  while i < arr.length() do
    if predicate(arr[i]) then
      return Some(arr[i])
    end
    i = i + 1
  done
  None

// ============================================================================
// 7. 배열 정렬
// ============================================================================

function array_sort(arr: Array[Int]): Array[Int] =
  // 버블 정렬 (간단한 구현)
  let n = arr.length()
  let sorted = arr
  let i = 0
  while i < n do
    let j = 0
    while j < n - i - 1 do
      if sorted[j] > sorted[j + 1] then
        // 스왑
        let temp = sorted[j]
        sorted[j] = sorted[j + 1]
        sorted[j + 1] = temp
      end
      j = j + 1
    done
    i = i + 1
  done
  sorted

// ============================================================================
// 8. 딕셔너리 (간단한 구현)
// ============================================================================

record DictEntry =
  key: String,
  value: Int

function dict_create(): Array[DictEntry] =
  Array[]

function dict_set(dict: Array[DictEntry], key: String, value: Int): Array[DictEntry] =
  let i = 0
  while i < dict.length() do
    if dict[i].key == key then
      // 기존 키 업데이트 (새 배열 반환)
      return dict
    end
    i = i + 1
  done
  // 새 항목 추가
  dict ++ Array[DictEntry(key=key, value=value)]

function dict_get(dict: Array[DictEntry], key: String): Option[Int] =
  let i = 0
  while i < dict.length() do
    if dict[i].key == key then
      return Some(dict[i].value)
    end
    i = i + 1
  done
  None

function dict_remove(dict: Array[DictEntry], key: String): Array[DictEntry] =
  let result = Array[]
  let i = 0
  while i < dict.length() do
    if dict[i].key != key then
      result = result ++ Array[dict[i]]
    end
    i = i + 1
  done
  result

function dict_keys(dict: Array[DictEntry]): Array[String] =
  let keys = Array[]
  let i = 0
  while i < dict.length() do
    keys = keys ++ Array[dict[i].key]
    i = i + 1
  done
  keys

function dict_values(dict: Array[DictEntry]): Array[Int] =
  let values = Array[]
  let i = 0
  while i < dict.length() do
    values = values ++ Array[dict[i].value]
    i = i + 1
  done
  values

// ============================================================================
// 9. 집합 (Set - 중복 없는 배열)
// ============================================================================

record SetOps =
  elements: Array[Int]

function set_create(arr: Array[Int]): SetOps =
  SetOps(elements=array_unique(arr))

function set_contains(s: SetOps, value: Int): Bool =
  array_contains(s.elements, value)

function set_add(s: SetOps, value: Int): SetOps =
  if set_contains(s, value) then
    s
  else
    SetOps(elements=s.elements ++ Array[value])
  end

function set_remove(s: SetOps, value: Int): SetOps =
  SetOps(elements=array_filter(s.elements, fn (x: Int) -> x != value))

function set_union(s1: SetOps, s2: SetOps): SetOps =
  let merged = s1.elements ++ s2.elements
  SetOps(elements=array_unique(merged))

function set_intersection(s1: SetOps, s2: SetOps): SetOps =
  let result = Array[]
  let i = 0
  while i < s1.elements.length() do
    if set_contains(s2, s1.elements[i]) then
      result = result ++ Array[s1.elements[i]]
    end
    i = i + 1
  done
  SetOps(elements=result)

// ============================================================================
// 10. 통합 테스트
// ============================================================================

function test_array_operations(): Bool =
  let arr = Array[1, 2, 3, 4, 5]

  // 기본 연산
  let len_ok = array_length(arr) == 5
  let get_ok = match array_get(arr, 0)
    case Some(x) -> x == 1
    case None -> false
  end

  // map
  let doubled = array_map_double(arr)
  let map_ok = array_length(doubled) == 5

  // filter
  let evens = array_filter_even(arr)
  let filter_ok = array_length(evens) == 2

  // fold
  let sum_ok = array_sum(arr) == 15
  let product_ok = array_product(arr) == 120

  // 검색
  let contains_ok = array_contains(arr, 3)
  let find_ok = match array_find(arr, fn (x: Int) -> x > 3)
    case Some(x) -> x >= 4
    case None -> false
  end

  len_ok && get_ok && map_ok && filter_ok && sum_ok && product_ok && contains_ok && find_ok

function main(): Unit =
  println("╔════════════════════════════════════════════╗")
  println("║  Array Operations - FreeLang Version      ║")
  println("╚════════════════════════════════════════════╝")
  println("")

  let arr = Array[1, 2, 3, 4, 5]

  println("Basic Operations:")
  println("  length([1,2,3,4,5]) = " ++ (array_length(arr)).to_string())
  println("  get([1,2,3,4,5], 0) = " ++ match array_get(arr, 0)
    case Some(x) -> x.to_string()
    case None -> "None"
  end)
  println("")

  println("Higher-Order Functions:")
  let doubled = array_map_double(arr)
  println("  map(double, [1,2,3,4,5]) length = " ++ (array_length(doubled)).to_string())

  let evens = array_filter_even(arr)
  println("  filter(even, [1,2,3,4,5]) length = " ++ (array_length(evens)).to_string())

  println("  sum([1,2,3,4,5]) = " ++ (array_sum(arr)).to_string())
  println("  product([1,2,3,4,5]) = " ++ (array_product(arr)).to_string())
  println("")

  println("Search Operations:")
  println("  contains([1,2,3,4,5], 3) = " ++ (array_contains(arr, 3)).to_string())
  println("  indexOf([1,2,3,4,5], 3) = " ++ match array_index_of(arr, 3)
    case Some(i) -> i.to_string()
    case None -> "None"
  end)
  println("")

  println("Dictionary Operations:")
  let dict = dict_create()
  let dict1 = dict_set(dict, "a", 10)
  let dict2 = dict_set(dict1, "b", 20)
  println("  dict[\"a\"] = " ++ match dict_get(dict2, "a")
    case Some(v) -> v.to_string()
    case None -> "None"
  end)
  println("")

  println("Set Operations:")
  let s1 = set_create(Array[1, 2, 3])
  let s2 = set_create(Array[2, 3, 4])
  let union = set_union(s1, s2)
  println("  union({1,2,3}, {2,3,4}) size = " ++ (array_length(union.elements)).to_string())
  println("")

  let test_result = test_array_operations()
  if test_result then
    println("✅ ALL ARRAY OPERATION TESTS PASSED")
  else
    println("❌ SOME ARRAY OPERATION TESTS FAILED")
  end

