package main

import (
	"fmt"
	"sort"
)

// ============================================================================
// 1. 기본 배열 연산
// ============================================================================

func arrayLength(arr []int) int {
	return len(arr)
}

func arrayGet(arr []int, index int) (int, bool) {
	if index >= 0 && index < len(arr) {
		return arr[index], true
	}
	return 0, false
}

func arraySet(arr []int, index int, value int) ([]int, bool) {
	if index >= 0 && index < len(arr) {
		arr[index] = value
		return arr, true
	}
	return arr, false
}

func arrayPush(arr []int, value int) []int {
	return append(arr, value)
}

func arrayPop(arr []int) ([]int, int, bool) {
	if len(arr) > 0 {
		last := arr[len(arr)-1]
		return arr[:len(arr)-1], last, true
	}
	return arr, 0, false
}

// ============================================================================
// 2. 고차함수: map
// ============================================================================

func arrayMap(arr []int, f func(int) int) []int {
	result := make([]int, len(arr))
	for i, v := range arr {
		result[i] = f(v)
	}
	return result
}

func arrayMapDouble(arr []int) []int {
	return arrayMap(arr, func(x int) int { return x * 2 })
}

func arrayMapSquare(arr []int) []int {
	return arrayMap(arr, func(x int) int { return x * x })
}

// ============================================================================
// 3. 고차함수: filter
// ============================================================================

func arrayFilter(arr []int, predicate func(int) bool) []int {
	var result []int
	for _, v := range arr {
		if predicate(v) {
			result = append(result, v)
		}
	}
	return result
}

func arrayFilterEven(arr []int) []int {
	return arrayFilter(arr, func(x int) bool { return x%2 == 0 })
}

func arrayFilterPositive(arr []int) []int {
	return arrayFilter(arr, func(x int) bool { return x > 0 })
}

// ============================================================================
// 4. 고차함수: fold (reduce)
// ============================================================================

func arrayFold(arr []int, init int, f func(int, int) int) int {
	acc := init
	for _, v := range arr {
		acc = f(acc, v)
	}
	return acc
}

func arraySum(arr []int) int {
	return arrayFold(arr, 0, func(acc, v int) int { return acc + v })
}

func arrayProduct(arr []int) int {
	return arrayFold(arr, 1, func(acc, v int) int { return acc * v })
}

func arrayMax(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	max := arr[0]
	for _, v := range arr {
		if v > max {
			max = v
		}
	}
	return max, true
}

func arrayMin(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	min := arr[0]
	for _, v := range arr {
		if v < min {
			min = v
		}
	}
	return min, true
}

// ============================================================================
// 5. 기본 배열 변환
// ============================================================================

func arrayReverse(arr []int) []int {
	result := make([]int, len(arr))
	for i, v := range arr {
		result[len(arr)-1-i] = v
	}
	return result
}

func arrayFlatten(arr [][]int) []int {
	var result []int
	for _, subArr := range arr {
		result = append(result, subArr...)
	}
	return result
}

func arrayUnique(arr []int) []int {
	m := make(map[int]bool)
	var result []int
	for _, v := range arr {
		if !m[v] {
			m[v] = true
			result = append(result, v)
		}
	}
	return result
}

// ============================================================================
// 6. 배열 검색
// ============================================================================

func arrayContains(arr []int, value int) bool {
	for _, v := range arr {
		if v == value {
			return true
		}
	}
	return false
}

func arrayIndexOf(arr []int, value int) (int, bool) {
	for i, v := range arr {
		if v == value {
			return i, true
		}
	}
	return -1, false
}

func arrayFind(arr []int, predicate func(int) bool) (int, bool) {
	for _, v := range arr {
		if predicate(v) {
			return v, true
		}
	}
	return 0, false
}

// ============================================================================
