// ============================================================================

func dictCreate() map[string]int {
	return make(map[string]int)
}

func dictSet(dict map[string]int, key string, value int) map[string]int {
	dict[key] = value
	return dict
}

func dictGet(dict map[string]int, key string) (int, bool) {
	v, ok := dict[key]
	return v, ok
}

func dictRemove(dict map[string]int, key string) map[string]int {
	delete(dict, key)
	return dict
}

func dictKeys(dict map[string]int) []string {
	var keys []string
	for k := range dict {
		keys = append(keys, k)
	}
	return keys
}

func dictValues(dict map[string]int) []int {
	var values []int
	for _, v := range dict {
		values = append(values, v)
	}
	return values
}

// ============================================================================
