	for _, v := range arr {
		s.elements[v] = true
	}
	return s
}

func setContains(s *SetOps, value int) bool {
	_, ok := s.elements[value]
	return ok
}

func setAdd(s *SetOps, value int) *SetOps {
	s.elements[value] = true
	return s
}

func setRemove(s *SetOps, value int) *SetOps {
	delete(s.elements, value)
	return s
}

func setUnion(s1, s2 *SetOps) *SetOps {
	result := &SetOps{elements: make(map[int]bool)}
	for k := range s1.elements {
		result.elements[k] = true
	}
	for k := range s2.elements {
		result.elements[k] = true
	}
	return result
}

func setIntersection(s1, s2 *SetOps) *SetOps {
	result := &SetOps{elements: make(map[int]bool)}
	for k := range s1.elements {
		if _, ok := s2.elements[k]; ok {
			result.elements[k] = true
		}
	}
	return result
}

func setSize(s *SetOps) int {
	return len(s.elements)
}

// ============================================================================
// 10. 통합 테스트
// ============================================================================

func testArrayOperations() bool {
	arr := []int{1, 2, 3, 4, 5}

	// 기본 연산
	lenOk := arrayLength(arr) == 5
	v, getOk := arrayGet(arr, 0)
	getOk = getOk && v == 1

