	productOk := arrayProduct(arr) == 120

	// 검색
	containsOk := arrayContains(arr, 3)
	v, findOk := arrayFind(arr, func(x int) bool { return x > 3 })
	findOk = findOk && v >= 4

	return lenOk && getOk && mapOk && filterOk && sumOk && productOk && containsOk && findOk
}

