	fmt.Println("║  Array Operations - Go Version            ║")
	fmt.Println("╚════════════════════════════════════════════╝")
	fmt.Println("")

	arr := []int{1, 2, 3, 4, 5}

	fmt.Println("Basic Operations:")
	fmt.Printf("  length([1,2,3,4,5]) = %d\n", arrayLength(arr))
	v, _ := arrayGet(arr, 0)
	fmt.Printf("  get([1,2,3,4,5], 0) = %d\n", v)
	fmt.Println("")

	fmt.Println("Higher-Order Functions:")
	doubled := arrayMapDouble(arr)
	fmt.Printf("  map(double, [1,2,3,4,5]) length = %d\n", arrayLength(doubled))

	evens := arrayFilterEven(arr)
	fmt.Printf("  filter(even, [1,2,3,4,5]) length = %d\n", arrayLength(evens))

	fmt.Printf("  sum([1,2,3,4,5]) = %d\n", arraySum(arr))
	fmt.Printf("  product([1,2,3,4,5]) = %d\n", arrayProduct(arr))
