	idx, _ := arrayIndexOf(arr, 3)
	fmt.Printf("  indexOf([1,2,3,4,5], 3) = %d\n", idx)
	fmt.Println("")

	fmt.Println("Dictionary Operations:")
	dict := dictCreate()
	dict = dictSet(dict, "a", 10)
	dict = dictSet(dict, "b", 20)
	v, _ := dictGet(dict, "a")
	fmt.Printf("  dict[\"a\"] = %d\n", v)
	fmt.Println("")

	fmt.Println("Set Operations:")
	s1 := setCreate([]int{1, 2, 3})
	s2 := setCreate([]int{2, 3, 4})
	union := setUnion(s1, s2)
	fmt.Printf("  union({1,2,3}, {2,3,4}) size = %d\n", setSize(union))
	fmt.Println("")

	testResult := testArrayOperations()
	if testResult {
		fmt.Println("✅ ALL ARRAY OPERATION TESTS PASSED")
	} else {
		fmt.Println("❌ SOME ARRAY OPERATION TESTS FAILED")
	}
}

