// 📊 Array/Collection Operations - C Version
//
// 목표: C의 동적 배열, 해시 테이블, 함수 포인터 검증
// 특징: 메모리 관리, 저수준 제어, 성능

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// ============================================================================
// 1. 동적 배열 구조
// ============================================================================

typedef struct {
	int *data;
	int size;
	int capacity;
} DynamicArray;

DynamicArray *array_create(int capacity) {
	DynamicArray *arr = (DynamicArray *)malloc(sizeof(DynamicArray));
	arr->data = (int *)malloc(sizeof(int) * capacity);
	arr->size = 0;
	arr->capacity = capacity;
	return arr;
}

void array_destroy(DynamicArray *arr) {
	if (arr) {
		free(arr->data);
		free(arr);
	}
}

int array_length(DynamicArray *arr) {
	return arr ? arr->size : 0;
}

bool array_get(DynamicArray *arr, int index, int *out_value) {
	if (arr && index >= 0 && index < arr->size) {
		*out_value = arr->data[index];
		return true;
	}
	return false;
}

bool array_set(DynamicArray *arr, int index, int value) {
	if (arr && index >= 0 && index < arr->size) {
		arr->data[index] = value;
		return true;
	}
	return false;
}

void array_push(DynamicArray *arr, int value) {
	if (!arr) return;

	if (arr->size >= arr->capacity) {
		arr->capacity *= 2;
		arr->data = (int *)realloc(arr->data, sizeof(int) * arr->capacity);
	}

	arr->data[arr->size++] = value;
}

bool array_pop(DynamicArray *arr, int *out_value) {
	if (arr && arr->size > 0) {
		*out_value = arr->data[--arr->size];
		return true;
	}
	return false;
}

// ============================================================================
// 2. 고차함수: map
// ============================================================================

typedef int (*IntFunction)(int);

DynamicArray *array_map(DynamicArray *arr, IntFunction f) {
	DynamicArray *result = array_create(arr->size);

	for (int i = 0; i < arr->size; i++) {
		array_push(result, f(arr->data[i]));
	}

	return result;
}

int double_fn(int x) { return x * 2; }
int square_fn(int x) { return x * x; }

DynamicArray *array_map_double(DynamicArray *arr) {
	return array_map(arr, double_fn);
}

DynamicArray *array_map_square(DynamicArray *arr) {
	return array_map(arr, square_fn);
}

// ============================================================================
// 3. 고차함수: filter
// ============================================================================

typedef bool (*BoolFunction)(int);

DynamicArray *array_filter(DynamicArray *arr, BoolFunction predicate) {
	DynamicArray *result = array_create(arr->size);

	for (int i = 0; i < arr->size; i++) {
		if (predicate(arr->data[i])) {
			array_push(result, arr->data[i]);
		}
	}

	return result;
}

bool is_even(int x) { return x % 2 == 0; }
bool is_positive(int x) { return x > 0; }

DynamicArray *array_filter_even(DynamicArray *arr) {
	return array_filter(arr, is_even);
}

DynamicArray *array_filter_positive(DynamicArray *arr) {
	return array_filter(arr, is_positive);
}

// ============================================================================
// 4. 고차함수: fold (reduce)
// ============================================================================

typedef int (*FoldFunction)(int, int);

