// 🧮 Advanced Calculator - Go Version
//
// 목표: Go의 모든 기능을 활용한 계산기
// 특징: 구조체, 메서드, 인터페이스, 에러 처리

package main

import (
	"fmt"
	"math"
)

// ============================================================================
// 1. 기본 데이터 타입
// ============================================================================

type CalculationResult struct {
	Expression   string
	Result       float64
	Operation    string
	Success      bool
	ErrorMessage string
}

type CalculatorState struct {
	History    []CalculationResult
	LastResult float64
	Memory     float64
	Precision  int
}

// ============================================================================
// 2. 기본 산술 연산
// ============================================================================

func add(a, b float64) float64 {
	return a + b
}

func subtract(a, b float64) float64 {
	return a - b
}

func multiply(a, b float64) float64 {
	return a * b
}

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, fmt.Errorf("division by zero")
	}
	return a / b, nil
}

func modulo(a, b int) (int, error) {
	if b == 0 {
		return 0, fmt.Errorf("modulo by zero")
	}
	return a % b, nil
}

// ============================================================================
// 3. 고급 연산
// ============================================================================

func power(base float64, exponent int) float64 {
	if exponent == 0 {
		return 1.0
	}
	return math.Pow(base, float64(exponent))
}

func factorial(n int) (int, error) {
	if n < 0 {
		return 0, fmt.Errorf("factorial of negative number")
	}
	result := 1
	for i := 1; i <= n; i++ {
		result *= i
	}
	return result, nil
}

func absolute(x float64) float64 {
	return math.Abs(x)
}

func squareRoot(x float64) (float64, error) {
	if x < 0 {
		return 0, fmt.Errorf("square root of negative number")
	}
	return math.Sqrt(x), nil
}

// ============================================================================
// 4. 통계 연산
// ============================================================================

func sumArray(arr []float64) float64 {
	sum := 0.0
	for _, v := range arr {
		sum += v
	}
	return sum
}

func average(arr []float64) (float64, error) {
	if len(arr) == 0 {
		return 0, fmt.Errorf("cannot calculate average of empty array")
	}
	return sumArray(arr) / float64(len(arr)), nil
}

func maxArray(arr []float64) (float64, error) {
	if len(arr) == 0 {
		return 0, fmt.Errorf("cannot find max of empty array")
	}
