		*error = 1;
		return 0.0;
	}
	return a / b;
}

int modulo_safe(int a, int b, int *error) {
	if (b == 0) {
		*error = 1;
		return 0;
	}
	return a % b;
}

// ============================================================================
// 3. 고급 연산
