double sum_array(double *arr, int size) {
	double sum = 0.0;
	for (int i = 0; i < size; i++) {
		sum += arr[i];
	}
	return sum;
}

double average_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	return sum_array(arr, size) / size;
}

double max_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double max = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] > max) {
			max = arr[i];
		}
	}
	return max;
}

double min_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double min = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] < min) {
			min = arr[i];
		}
	}
	return min;
