double subtract(double a, double b) {
	return a - b;
}

double multiply(double a, double b) {
	return a * b;
}

double divide_safe(double a, double b, int *error) {
	if (b == 0.0) {
		*error = 1;
		return 0.0;
	}
	return a / b;
}

int modulo_safe(int a, int b, int *error) {
	if (b == 0) {
		*error = 1;
		return 0;
	}
	return a % b;
}

// ============================================================================
