// ============================================================================

double power_func(double base, int exponent) {
	return pow(base, (double)exponent);
}

int factorial_safe(int n, int *error) {
	if (n < 0) {
		*error = 1;
		return 0;
	}
	int result = 1;
	for (int i = 1; i <= n; i++) {
		result *= i;
	}
	return result;
}

double absolute_val(double x) {
