	}
	return sum;
}

double average_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	return sum_array(arr, size) / size;
}

double max_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double max = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] > max) {
			max = arr[i];
		}
	}
	return max;
}

double min_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double min = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] < min) {
			min = arr[i];
		}
	}
	return min;
}

double variance_safe(double *arr, int size, int *error) {
	double avg = average_safe(arr, size, error);
	if (*error) return 0.0;

	double sum_sq = 0.0;
	for (int i = 0; i < size; i++) {
		double diff = arr[i] - avg;
		sum_sq += diff * diff;
	}
	return sum_sq / size;
}

double standard_deviation_safe(double *arr, int size, int *error) {
	double var = variance_safe(arr, size, error);
